using ProjetoIntegradorBack.Domain.Entities;
using ProjetoIntegradorBack.Domain.Interfaces;
using ProjetoIntegradorBack.Infrastructure.Context;
using ProjetoIntegradorBack.Shared.Pattern;
using Microsoft.EntityFrameworkCore;
namespace ProjetoIntegradorBack.Infrastructure.Repositories;
public class EstabelecimentoRepository(ProjetoIntegradorBackDbContext context) : IEstabelecimentoRepository
{
    public async Task<Result<Estabelecimento>> ObterPorIdAsync(Guid id, CancellationToken ct=default){try{var e=await context.Estabelecimentos.Include(x=>x.Funcionarios).Include(x=>x.Servicos).FirstOrDefaultAsync(x=>x.Id==id,ct);return e==null?Result<Estabelecimento>.AsFailure(new Failure(404,"Estabelecimento não encontrado.")):Result<Estabelecimento>.AsSuccess(e);}catch(Exception ex){return Result<Estabelecimento>.AsFailure(new Failure(500,ex.Message));}}
    public async Task<Result<IReadOnlyList<Estabelecimento>>> ListarAsync(string? busca,string? cidade,int pagina,int tamanho,CancellationToken ct=default){try{var q=context.Estabelecimentos.Where(x=>x.Ativo);if(!string.IsNullOrWhiteSpace(busca))q=q.Where(x=>x.NomeFantasia.Contains(busca)||x.RazaoSocial.Contains(busca));if(!string.IsNullOrWhiteSpace(cidade))q=q.Where(x=>x.Endereco.Cidade==cidade);return Result<IReadOnlyList<Estabelecimento>>.AsSuccess(await q.Skip((pagina-1)*tamanho).Take(tamanho).ToListAsync(ct));}catch(Exception ex){return Result<IReadOnlyList<Estabelecimento>>.AsFailure(new Failure(500,ex.Message));}}
    public async Task<Result<int>> ContarAsync(string? busca,string? cidade,CancellationToken ct=default){try{var q=context.Estabelecimentos.Where(x=>x.Ativo);if(!string.IsNullOrWhiteSpace(busca))q=q.Where(x=>x.NomeFantasia.Contains(busca)||x.RazaoSocial.Contains(busca));if(!string.IsNullOrWhiteSpace(cidade))q=q.Where(x=>x.Endereco.Cidade==cidade);return Result<int>.AsSuccess(await q.CountAsync(ct));}catch(Exception ex){return Result<int>.AsFailure(new Failure(500,ex.Message));}}
    public async Task<Result<Estabelecimento>> AdicionarAsync(Estabelecimento e,CancellationToken ct=default){try{e.Id=Guid.NewGuid();e.CriadoEm=DateTime.UtcNow;await context.Estabelecimentos.AddAsync(e,ct);await context.SaveChangesAsync(ct);return Result<Estabelecimento>.AsSuccess(e);}catch(Exception ex){return Result<Estabelecimento>.AsFailure(new Failure(500,ex.Message));}}
    public async Task<Result<Estabelecimento>> AtualizarAsync(Estabelecimento e,CancellationToken ct=default){try{e.AtualizadoEm=DateTime.UtcNow;context.Estabelecimentos.Update(e);await context.SaveChangesAsync(ct);return Result<Estabelecimento>.AsSuccess(e);}catch(Exception ex){return Result<Estabelecimento>.AsFailure(new Failure(500,ex.Message));}}
    public async Task<Result<string>> DesativarAsync(Guid id,CancellationToken ct=default){try{var e=await context.Estabelecimentos.FindAsync(new object[]{id},ct);if(e==null)return Result<string>.AsFailure(new Failure(404,"Estabelecimento não encontrado."));e.Ativo=false;e.AtualizadoEm=DateTime.UtcNow;await context.SaveChangesAsync(ct);return Result<string>.AsSuccess("Estabelecimento desativado com sucesso.");}catch(Exception ex){return Result<string>.AsFailure(new Failure(500,ex.Message));}}
}